import { test } from 'node:test';
import assert from 'node:assert';
import { 
  createState, 
  frame, 
  WIDTH, 
  HEIGHT, 
  BALL_R, 
  BRICK_W, 
  BRICK_H, 
  BRICK_TOP, 
  BRICK_GAP 
} from './game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
  stroke: () => {},
};

test('D1 - Ball should bounce off brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball to collide with the top of the brick
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - BALL_R + 1; // slightly overlapping the top
  state.ball.vy = 100; // moving down

  const vyBefore = state.ball.vy;
  frame(mockCtx, state);

  assert.notStrictEqual(state.ball.vy, vyBefore, 'Ball velocity vy should have changed after hitting brick');
});

test('D2 - Ball should be repositioned after collision to avoid sticking', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - BALL_R + 1; 
  state.ball.vy = 100;

  frame(mockCtx, state);

  // If a bounce occurred, the ball should ideally be pushed out of the brick
  // so that it doesn't collide again immediately if it weren't for the brick being destroyed.
  // But since bricks are destroyed, we test if it's still overlapping.
  // Actually, for a single brick, it's destroyed, so it won't collide again.
  // But the invariant is "After resolution, the ball is hors du rectangle".

  const isOverlapping = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );

  assert.strictEqual(isOverlapping, false, 'Ball should be repositioned outside the brick after collision');
});

test('D3 - Corner collision should flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball to hit the top-left corner
  state.ball.x = brick.x - BALL_R + 1;
  state.ball.y = brick.y - BALL_R + 1;
  state.ball.vx = 100; 
  state.ball.vy = 100;

  frame(mockCtx, state);

  assert.strictEqual(Math.sign(state.ball.vx), -1, 'vx should be flipped on corner hit');
  assert.strictEqual(Math.sign(state.ball.vy), -1, 'vy should be flipped on corner hit');
});

test('D4 - Seam collision should not double-invert', () => {
  const state = createState(1);
  // Use two adjacent bricks in the same row
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];

  // Position ball so it overlaps both bricks (seam)
  // BRICK_GAP = 8, BALL_R = 7. Ball diameter = 14.
  // brick1.x + brick1.w is the right edge.
  // ball.x is center. 
  // ball.x - 7 < brick1.x + brick1.w AND ball.x + 7 > brick2.x
  state.ball.x = brick1.x + brick1.w + BRICK_GAP / 2;
  state.ball.y = brick1.y + BRICK_H / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  const vxBefore = state.ball.vx;
  frame(mockCtx, state);

  // If it hit both, and both flipped vx, we'd be back to 100.
  // It should have flipped once.
  assert.strictEqual(Math.sign(state.ball.vx), -1, 'vx should be inverted once even when hitting a seam');
});

# Playtest: Ball passes through bricks

Symptôme joueur : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond
- **Famille** : Logique manquante
- **Symptôme joueur** : La balle traverse la brique sans changer de direction.
- **Cause** : `game/neon.js:214` — La collision est détectée (`collides`), la brique est détruite, mais la vitesse de la balle n'est jamais modifiée.
- **Invariant violé** : Toute collision avec une brique doit entraîner un changement de trajectoire.
- **Déclencheur** : N'importe quelle collision balle/brique.
- **Attendu** : `state.ball.vy` ou `state.ball.vx` doit être inversé.
- **Référence** : AABB Collision Response
- **Cas test** : 
  ```js
  test('D1 - Ball should bounce off brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - BALL_R + 1; 
    state.ball.vy = 100;
    const vyBefore = state.ball.vy;
    frame(mockCtx, state);
    assert.notStrictEqual(state.ball.vy, vyBefore);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball velocity vy should have changed after hitting brick`
- **Discrimine** : La correction naïve qui oublierait d'implémenter le rebond.
- **Vert quand** : La vitesse est modifiée après `frame()`.

## D2 — Recouvrement non résolu (Collant)
- **Famille** : Collant
- **Symptôme joueur** : La balle peut sembler "glisser" ou rester coincée si elle ne sort pas immédiatement de l'obstacle.
- **Cause** : `game/neon.js:214` — Absence de repositionnement de la balle après le rebond.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : Collision où la balle pénètre profondément dans la brique avant le rebond.
- **Attendu** : La balle est repositionnée pour ne plus chevaucher la brique.
- **Référence** : AABB Collision Resolution
- **Cas test** :
  ```js
  test('D2 - Ball should be repositioned after collision to avoid sticking', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + BRICK_W / 2;
    state.ball.y = brick.y - BALL_R + 1; 
    state.ball.vy = 100;
    frame(mockCtx, state);
    const isOverlapping = collides(state.ball, brick);
    assert.strictEqual(isOverlapping, false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be repositioned outside the brick after collision`
- **Discrimine** : La correction naïve qui inverse la vitesse sans repositionner la balle.
- **Vert quand** : `collides(ball, brick)` est faux après la résolution.

## D3 — Collision de coin (Face vs Coin)
- **Famille** : Face vs coin
- **Symptôme joueur** : La balle frappe un coin et ne rebondit que sur un axe, traversant partiellement la brique.
- **Cause** : `game/neon.js:214` — Absence de détection de l'axe de collision.
- **Invariant violé** : Une collision sur un coin doit inverser les deux composantes de la vitesse (`vx` et `vy`).
- **Déclencheur** : Position de la balle telle qu'elle touche simultanément le haut et le côté d'une brique.
- **Attendu** : `state.ball.vx` ET `state.ball.vy` sont inversés.
- **Référence** : AABB Corner Resolution
- **Cas test** :
  ```js
  test('D3 - Corner collision should flip both axes', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - BALL_R + 1;
    state.ball.y = brick.y - BALL_R + 1;
    state.ball.vx = 100; 
    state.ball.vy = 100;
    frame(mockCtx, state);
    assert.strictEqual(Math.sign(state.ball.vx), -1);
    assert.strictEqual(Math.sign(state.ball.vy), -1);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: vx should be flipped on corner hit`
- **Discrimine** : La correction naïve qui n'inverse qu'un seul axe (celui de la plus petite pénétration).
- **Vert quand** : Les deux axes sont inversés lors d'un impact de coin.

## D4 — Double inversion (Seam/Ghost)
- **Famille** : Double inversion
- **Symptôme joueur** : La balle traverse une couture verticale entre deux briques.
- **Cause** : `game/neon.js:214` — La boucle `for (const brick of state.bricks)` traite chaque brique indépendamment. Si la balle touche deux briques, elle subit deux inversions de vitesse.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : `BRICK_GAP (8) < 2 * BALL_R (14)`. La balle chevauche deux briques adjacentes.
- **Attendu** : La vitesse n'est inversée qu'une seule fois même si plusieurs briques sont touchées.
- **Référence** : Tile seam ghost collision
- **Cas test** :
  ```js
  test('D4 - Seam collision should not double-invert', () => {
    const state = createState(1);
    const brick1 = state.bricks[0];
    const brick2 = state.bricks[1];
    state.ball.x = brick1.x + brick1.w + BRICK_GAP / 2;
    state.ball.y = brick1.y + BRICK_H / 2;
    state.ball.vx = 100;
    state.ball.vy = 0;
    frame(mockCtx, state);
    assert.strictEqual(Math.sign(state.ball.vx), -1);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: vx should be inverted once even when hitting a seam`
- **Discrimine** : La correction naïve qui boucle sur toutes les briques et inverse la vitesse pour chacune.
- **Vert quand** : La vitesse est inversée une seule fois par frame.

import { test } from 'node:test';
import assert from 'node:assert';
import { 
  createState, 
  frame, 
  WIDTH, 
  HEIGHT, 
  BALL_R, 
  BRICK_W, 
  BRICK_H, 
  BRICK_TOP, 
  BRICK_GAP 
} from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
  stroke: () => {},
};

test('D1 - Ball should bounce off brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - BALL_R + 1; 
  state.ball.vy = 100;
  const vyBefore = state.ball.vy;
  frame(mockCtx, state);
  assert.notStrictEqual(state.ball.vy, vyBefore, 'Ball velocity vy should have changed after hitting brick');
});

test('D2 - Ball should be repositioned after collision to avoid sticking', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + BRICK_W / 2;
  state.ball.y = brick.y - BALL_R + 1; 
  state.ball.vy = 100;
  frame(mockCtx, state);
  const isOverlapping = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );
  assert.strictEqual(isOverlapping, false, 'Ball should be repositioned outside the brick after collision');
});

test('D3 - Corner collision should flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - BALL_R + 1;
  state.ball.y = brick.y - BALL_R + 1;
  state.ball.vx = 100; 
  state.ball.vy = 100;
